                        if (magnitude > 92) throw std::runtime_error("Paracine trap: fib index outside signed 64-bit result range (-92..92)");
                        std::int64_t previous = 0, current = 1;
                        for (std::uint64_t i = 1; i < magnitude; ++i) { const auto next = previous + current; previous = current; current = next; }
                        auto value = magnitude == 0 ? std::int64_t{ 0 } : current;
                        if (negative && magnitude % 2 == 0) value = -value;
