                              // an installed lld-link performs arbitrary third-party COFF/archive resolution.
                              // This deliberately does not claim to be Paracine's future built-in linker.
                              static int executeArgv(const std::vector<std::string>& argv) {
                                  if (argv.empty())throw std::runtime_error("external linker command is empty");
#ifdef _WIN32
                                  auto wide = [](const std::string& s)->std::wstring {
                                      if (s.empty())return {};
                                      const int n = MultiByteToWideChar(CP_UTF8, MB_ERR_INVALID_CHARS, s.c_str(), static_cast<int>(s.size()), nullptr, 0);
                                      if (n <= 0)throw std::runtime_error("invalid UTF-8 in linker argument");
                                      std::wstring out(static_cast<std::size_t>(n), L'\0');
                                      if (MultiByteToWideChar(CP_UTF8, MB_ERR_INVALID_CHARS, s.c_str(), static_cast<int>(s.size()), out.data(), n) != n)
                                          throw std::runtime_error("linker argument conversion failed");
                                      return out;
                                      };
                                  auto quote = [](const std::wstring& a)->std::wstring {
                                      std::wstring out = L"\""; std::size_t slash = 0;
                                      for (wchar_t ch : a) {
                                          if (ch == L'\\') { ++slash; continue; }
                                          if (ch == L'"') { out.append(slash * 2 + 1, L'\\'); out += ch; slash = 0; continue; }
                                          out.append(slash, L'\\'); slash = 0; out += ch;
                                      }
                                      out.append(slash * 2, L'\\'); out += L'"'; return out;
                                      };
                                  std::wstring cmd;
                                  for (const auto& a : argv) { if (!cmd.empty())cmd += L' '; cmd += quote(wide(a)); }
                                  std::vector<wchar_t> mutableCmd(cmd.begin(), cmd.end()); mutableCmd.push_back(L'\0');
                                  STARTUPINFOW si{}; si.cb = sizeof(si); PROCESS_INFORMATION pi{};
                                  if (!CreateProcessW(nullptr, mutableCmd.data(), nullptr, nullptr, FALSE, 0, nullptr, nullptr, &si, &pi))
                                      throw std::runtime_error("cannot start external linker (lld-link or configured path): Win32 error " + std::to_string(GetLastError()));
                                  CloseHandle(pi.hThread);
                                  DWORD exitCode = 1;
                                  const DWORD waited = WaitForSingleObject(pi.hProcess, INFINITE);
                                  if (waited == WAIT_OBJECT_0)GetExitCodeProcess(pi.hProcess, &exitCode);
                                  CloseHandle(pi.hProcess);
                                  if (waited != WAIT_OBJECT_0)throw std::runtime_error("external linker process wait failed");
                                  return static_cast<int>(exitCode);
#else
                                  pid_t pid = fork();
                                  if (pid < 0)throw std::runtime_error("failed to create external linker process");
                                  if (pid == 0) {
                                      std::vector<char*> raw; raw.reserve(argv.size() + 1);
                                      for (const auto& a : argv)raw.push_back(const_cast<char*>(a.c_str()));
                                      raw.push_back(nullptr);
                                      execvp(raw.front(), raw.data()); _exit(127);
                                  }
                                  int status = 0;
                                  while (waitpid(pid, &status, 0) < 0) { if (errno == EINTR)continue; throw std::runtime_error("failed waiting for external linker"); }
                                  if (!WIFEXITED(status))throw std::runtime_error("external linker terminated abnormally");
                                  return WEXITSTATUS(status);
#endif
                              }

                              static std::string combineLtoSources(const std::vector<std::string>& sources) {
                                  if (sources.empty()) throw std::runtime_error("--lto requires at least one .pcn source");
                                  std::vector<std::filesystem::path> seen;
                                  std::map<std::string, std::string> routineDefinitions;
                                  std::string combined;
                                  for (const auto& source : sources) {
                                      const auto path = std::filesystem::canonical(filesystemPathFromUtf8(source));
                                      for (const auto& previous : seen)
                                          if (std::filesystem::equivalent(path, previous)) throw std::runtime_error("--lto duplicate source: " + source);
                                      seen.push_back(path);
                                      auto text = Lexer::normalizeSource(readSourceFile(path));
                                      const auto tokens = Lexer(text).tokenize();
                                      const auto unit = Parser(tokens).parse();
                                      std::vector<std::size_t> lineOffsets{ 0 };
                                      for (std::size_t offset = 0; offset < text.size(); ++offset)
                                          if (text[offset] == '\n') lineOffsets.push_back(offset + 1);
                                      std::vector<std::pair<std::size_t, std::size_t>> duplicates;
                                      for (const auto& routine : unit.routines) {
                                          std::size_t endLine = lineOffsets.size() + 1;
                                          for (const auto& next : unit.routines)
                                              if (next.location.line > routine.location.line) endLine = std::min(endLine, next.location.line);
                                          for (const auto& next : unit.declarations)
                                              if (next.location.line > routine.location.line) endLine = std::min(endLine, next.location.line);
                                          std::string fingerprint;
                                          if (!routine.genericParameters.empty()) {
                                              std::vector<const Token*> definitionTokens;
                                              for (const auto& token : tokens) {
                                                  if (token.kind == TokenKind::EndOfFile || token.location.line < routine.location.line || token.location.line >= endLine) continue;
                                                  definitionTokens.push_back(&token);
                                              }
                                              auto boundaryLayout = [](const Token* token) {
                                                  return token->kind == TokenKind::Newline || token->kind == TokenKind::Indent || token->kind == TokenKind::Dedent;
                                              };
                                              std::size_t begin = 0, end = definitionTokens.size();
                                              while (begin < end && boundaryLayout(definitionTokens[begin])) ++begin;
                                              while (end > begin && boundaryLayout(definitionTokens[end - 1])) --end;
                                              for (auto index = begin; index < end; ++index) {
                                                  const auto* token = definitionTokens[index];
                                                  fingerprint += std::to_string(static_cast<int>(token->kind)) + ":" + std::to_string(token->text.size()) + ":" + token->text;
                                              }
                                          }
                                          const auto [definition, inserted] = routineDefinitions.emplace(routine.name, fingerprint);
                                          if (inserted) continue;
                                          if (fingerprint.empty() || definition->second.empty())
                                              throw std::runtime_error("--lto duplicate or overloaded routine name: " + routine.name);
                                          if (fingerprint != definition->second)
                                              throw std::runtime_error("E0349 --lto conflicting generic definitions for '" + routine.name + "' in " + source);
                                          const auto begin = lineOffsets.at(routine.location.line - 1);
                                          const auto end = endLine > lineOffsets.size() ? text.size() : lineOffsets.at(endLine - 1);
                                          duplicates.push_back({ begin,end });
                                      }
                                      for (const auto& [begin, end] : duplicates)
                                          for (auto offset = begin; offset < end; ++offset) if (text[offset] != '\n') text[offset] = ' ';
                                      for (const auto& declaration : unit.declarations) {
                                          if (std::holds_alternative<ModuleDecl>(declaration.node)) {
                                              if (seen.size() != 1)
                                                  throw std::runtime_error("--lto supports a module header only in the first source unit: " + source);
                                          }
                                          else if (std::holds_alternative<Routine>(declaration.node))
                                              throw std::runtime_error("--lto public or compile routine declarations are not supported: " + source);
                                          else if (std::holds_alternative<UseDecl>(declaration.node) || std::holds_alternative<ForeignDecl>(declaration.node))
                                              throw std::runtime_error("--lto source imports and foreign declarations are not supported: " + source);
                                      }
                                      combined += text;
                                      combined += '\n';
                                  }
                                  return combined;
                              }

                              #include "native_debug.h"

                              static int runExternalCOFFLink(const std::vector<std::string>& args) {
                                  std::vector<std::string> sources;
                                  std::string output, entry = "main", executable = "lld-link", subsystem = "console";
                                  std::vector<std::string> otherInputs, searchPaths, defaultLibs, wholeArchives;
                                  std::string importLibrary;
                                  bool noDefaultLib = true;
                                  bool dll = false, lto = false, debug = false;
                                  int optimizationLevel = 2;
                                  bool entrySet = false, linkerSet = false, subsystemSet = false, dllSet = false;
                                  std::unordered_set<std::string> seenSources, seenInputs;
                                  std::unordered_set<std::string> seenDefaultLibs, seenWholeArchives;
                                  const bool ltoRequested = std::find(args.begin(), args.end(), "--lto") != args.end();
                                  auto lowerExt = [](std::string ext) {
                                      std::transform(ext.begin(), ext.end(), ext.begin(), [](unsigned char ch) {
                                          return static_cast<char>(std::tolower(ch));
                                          });
                                      return ext;
                                      };
                                  for (std::size_t i = 1; i < args.size(); ++i) {
                                      const auto& a = args[i];
                                      if ((a == "-o" || a == "--out") && i + 1 < args.size())output = args[++i];
                                      else if (a == "-g") debug = true;
                                      else if (a.size() == 3 && a[0] == '-' && a[1] == 'O' && a[2] >= '0' && a[2] <= '3') optimizationLevel = a[2] - '0';
                                      else if (a == "--entry" && i + 1 < args.size()) {
                                          if (entrySet)throw std::runtime_error("duplicate --entry option");
                                          entry = args[++i];
                                          entrySet = true;
                                      }
                                      else if (a == "--linker" && i + 1 < args.size()) {
                                          if (linkerSet)throw std::runtime_error("duplicate --linker option");
                                          executable = args[++i];
                                          linkerSet = true;
                                      }
                                      else if (a == "--libpath" && i + 1 < args.size())searchPaths.push_back(args[++i]);
                                      else if ((a == "--defaultlib" || a == "--lib" || a == "--library") && i + 1 < args.size()) {
                                          const auto lib = args[++i];
                                          if (seenDefaultLibs.insert(lib).second)defaultLibs.push_back(lib);
                                          noDefaultLib = false;
                                      }
                                      else if (a == "--wholearchive" && i + 1 < args.size()) {
                                          const auto archive = args[++i];
                                          if (!std::filesystem::exists(archive))throw std::runtime_error("whole-archive input does not exist: " + archive);
                                          if (seenWholeArchives.insert(archive).second)wholeArchives.push_back(archive);
                                      }
                                      else if (a == "--implib" && i + 1 < args.size())importLibrary = args[++i];
                                      else if (a == "--use-defaultlibs")noDefaultLib = false;
                                      else if (a == "--subsystem" && i + 1 < args.size()) {
                                          if (subsystemSet)throw std::runtime_error("duplicate --subsystem option");
                                          subsystem = args[++i];
                                          subsystemSet = true;
                                      }
                                      else if (a == "--dll") {
                                          if (dllSet)throw std::runtime_error("duplicate --dll option");
                                          dll = true;
                                          dllSet = true;
                                      }
                                      else if (a == "--lto") {
                                          if (lto) throw std::runtime_error("duplicate --lto option");
                                          lto = true;
                                      }
                                      else if (a.size() && a[0] == '-')throw std::runtime_error("unsupported link argument: " + a);
                                      else if (lowerExt((ltoRequested ? filesystemPathFromUtf8(a) : std::filesystem::path(a)).extension().string()) == ".pcn") {
                                          if (!seenSources.insert(a).second)throw std::runtime_error("duplicate source input: " + a);
                                          sources.push_back(a);
                                      }
                                      else {
                                          auto ext = lowerExt((ltoRequested ? filesystemPathFromUtf8(a) : std::filesystem::path(a)).extension().string());
                                          if (ext != ".obj" && ext != ".lib" && ext != ".res" && ext != ".exp" && ext != ".def")throw std::runtime_error("external link input must be .pcn, .obj, .lib, .res, .exp, or .def: " + a);
                                          if (!(ltoRequested ? std::filesystem::exists(filesystemPathFromUtf8(a)) : std::filesystem::exists(a)))throw std::runtime_error("external link input does not exist: " + a);
                                          if (!seenInputs.insert(a).second)throw std::runtime_error("duplicate native link input: " + a);
                                          otherInputs.push_back(a);
                                      }
                                  }
                                  if (sources.empty() && otherInputs.empty())throw std::runtime_error("link requires .pcn or COFF objects/libraries");
                                  if (debug && lto) throw std::runtime_error("E0580 source-concatenating --lto does not preserve independent debug source identities");
                                  if (subsystem != "console" && subsystem != "windows")throw std::runtime_error("link subsystem must be console or windows");
                                  if (!importLibrary.empty() && !dll)throw std::runtime_error("--implib requires --dll");
                                  if (lto && (sources.empty() || !otherInputs.empty() || !wholeArchives.empty() || !defaultLibs.empty() || !searchPaths.empty() || !noDefaultLib || dll))
                                      throw std::runtime_error("--lto currently requires source-only executable inputs without libraries or DLL output");
                                  if (!noDefaultLib && defaultLibs.empty()) {
                                      // Canonical Windows user-mode default import set for this toolchain.
                                      defaultLibs = { "kernel32.lib", "user32.lib", "advapi32.lib" };
                                  }
                                  if (output.empty()) {
                                      std::filesystem::path sample = lto ? filesystemPathFromUtf8(sources.front()) :
                                          (sources.empty() ? std::filesystem::path(otherInputs.front()) : std::filesystem::path(sources.front()));
                                      sample.replace_extension(dll ? ".dll" : ".exe");
                                      if (lto) { const auto utf8 = sample.u8string(); output.assign(utf8.begin(), utf8.end()); }
                                      else output = sample.string();
                                  }
                                  struct Scratch {
                                      std::vector<std::filesystem::path> files;
                                      ~Scratch() { std::error_code ec; for (const auto& file : files)std::filesystem::remove(file, ec); }
                                  } scratch;
                                  if (lto) {
                                      for (const auto& source : sources) {
                                          std::error_code ec;
                                          if (std::filesystem::equivalent(filesystemPathFromUtf8(source), filesystemPathFromUtf8(output), ec) && !ec)
                                              throw std::runtime_error("--lto output must not overwrite a source input");
                                      }
                                      const auto combined = combineLtoSources(sources);
                                      CompilerOptions options; options.optimizationLevel = 3; options.entry = entry;
                                      const auto artifacts = compileAll(combined, options);
                                      if (!artifacts.analysis.succeeded()) { printSemanticDiagnostics(artifacts.analysis, "<combined LTO source>", combined); return 1; }
                                      if (artifacts.machine.entryName != entry)
                                          throw std::runtime_error("--lto entry must be the selected zero-argument routine; argument entry wrappers are not supported");
                                      if (!artifacts.machine.imports.empty())
                                          throw std::runtime_error("--lto currently does not support external native imports");
                                      const auto obj = PECOFFGenerator{}.emitObject(artifacts.pcir, artifacts.pmir, artifacts.machine);
                                      std::filesystem::path temporaryDirectory;
                                      std::random_device random;
                                      for (int attempt = 0; attempt < 32; ++attempt) {
                                          const auto candidate = std::filesystem::temp_directory_path() /
                                              ("paracine-lto-" + std::to_string(random()) + "-" + std::to_string(random()));
                                          std::error_code ec;
                                          if (std::filesystem::create_directory(candidate, ec)) { temporaryDirectory = candidate; break; }
                                          if (ec) throw std::runtime_error("failed to create LTO scratch directory: " + ec.message());
                                      }
                                      if (temporaryDirectory.empty()) throw std::runtime_error("failed to allocate unique LTO scratch directory");
                                      struct LtoScratchDirectory { std::filesystem::path path; ~LtoScratchDirectory() { std::error_code ec; std::filesystem::remove(path / "program.obj", ec); std::filesystem::remove(path, ec); } } directory{ temporaryDirectory };
                                      const auto object = temporaryDirectory / "program.obj";
                                      std::ofstream objectFile(object, std::ios::binary);
                                      if (!objectFile) throw std::runtime_error("failed to create LTO object");
                                      objectFile.write(reinterpret_cast<const char*>(obj.data()), static_cast<std::streamsize>(obj.size()));
                                      objectFile.close();
                                      if (!objectFile) throw std::runtime_error("failed to write LTO object");
                                      const auto objectUtf8 = object.u8string();
                                      std::vector<std::string> invocation = { executable, "/nologo", "/machine:x64", "/nodefaultlib", "/subsystem:" + subsystem, "/entry:" + entry, "/out:" + output, std::string(objectUtf8.begin(), objectUtf8.end()) };
                                      const int result = executeArgv(invocation);
                                      if (result) throw std::runtime_error("external COFF link failed with exit code " + std::to_string(result));
                                      if (!std::filesystem::exists(filesystemPathFromUtf8(output))) throw std::runtime_error("external linker succeeded without producing output");
                                      std::cout << "source LTO link succeeded: " << output << "\n";
                                      return 0;
                                  }
                                  std::map<std::string, std::string> linkedSpecializations;
                                  for (std::size_t i = 0; i < sources.size(); ++i) {
                                      const auto& source = sources[i];
                                      auto options = CompilerOptions{}; options.debugInfo = debug; options.optimizationLevel = optimizationLevel; options.objectOnly = true;
                                      const auto artifacts = compileAll(readSourceFile(source), options, debug, nullptr, source);
                                      if (!artifacts.analysis.succeeded()) { printSemanticDiagnostics(artifacts.analysis); return 1; }
                                      for (const auto& instance : artifacts.analysis.skm.specializations) {
                                          const auto [previous, inserted] = linkedSpecializations.emplace(instance.specializationName, source);
                                          if (!inserted) throw std::runtime_error("E0530 repeated generic specialization across separately compiled units '" +
                                              previous->second + "' and '" + source + "'; use source-only --lto for checked cross-unit deduplication");
                                      }
                                      const auto obj = debug ? native_debug::object(artifacts, options) : PECOFFGenerator{}.emitObject(artifacts.pcir, entry);
                                      auto temp = std::filesystem::path(output);
                                      temp += ".paracine-link-temp-" + std::to_string(i) + ".obj";
                                      writeBinaryFile(temp, obj);
                                      scratch.files.push_back(std::move(temp));
                                  }
                                  std::vector<std::string> invocation = { executable,"/nologo","/machine:x64","/out:" + output };
                                  if (debug) {
                                      auto pdb = std::filesystem::path(output); pdb.replace_extension(".pdb");
                                      if (pdb == std::filesystem::path(output)) throw std::runtime_error("E0580 executable and PDB paths must differ");
                                      invocation.insert(invocation.end(), { "/debug:full", "/incremental:no", "/opt:noref,noicf", "/pdb:" + pdb.string() });
                                  }
                                  if (noDefaultLib)invocation.push_back("/nodefaultlib");
                                  invocation.push_back("/subsystem:" + subsystem);
                                  if (dll) {
                                      invocation.push_back("/dll");
                                      invocation.push_back("/noentry");
                                      if (!importLibrary.empty())invocation.push_back("/implib:" + importLibrary);
                                  }
                                  else invocation.push_back("/entry:" + entry);
                                  for (const auto& dir : searchPaths)invocation.push_back("/libpath:" + dir);
                                  for (const auto& lib : defaultLibs)invocation.push_back("/defaultlib:" + lib);
                                  for (const auto& lib : wholeArchives)invocation.push_back("/wholearchive:" + lib);
                                  for (const auto& file : scratch.files)invocation.push_back(file.string());
                                  for (const auto& arg : otherInputs)invocation.push_back(arg);
                                  const int result = executeArgv(invocation);
                                  if (result)throw std::runtime_error("external COFF link failed with exit code " + std::to_string(result));
                                  if (!std::filesystem::exists(output))throw std::runtime_error("external linker succeeded without producing output");
                                  if (debug && !std::filesystem::is_regular_file(withExtension(output, ".pdb"))) throw std::runtime_error("E0580 external debug linker did not produce a PDB");
                                  std::cout << "external COFF link succeeded: " << output << "\n";
                                  return 0;
                              }

                              // --- Developer workflows: conservative formatting, deterministic packaging,
                              //     compiler-phase profiling, project creation and environment diagnostics. ---
                              // These tools don't change the language's supported semantic surface.
                              static std::string canonicalFormat(const std::string& source) {
                                  // Whitespace-only normalization: line-ending normalization, trailing-space
                                  // removal and a final newline. Do not rewrite operator spacing, identifier
                                  // spelling, string contents, indentation, or comments.
                                  std::string formatted;
                                  formatted.reserve(source.size() + 1);
                                  std::size_t lineStart = 0;
                                  for (std::size_t i = 0; i < source.size(); ++i) {
                                      if (source[i] == '\r' || source[i] == '\n') {
                                          std::size_t end = i;
                                          while (end > lineStart && (source[end - 1] == ' ' || source[end - 1] == '\t')) --end;
                                          formatted.append(source, lineStart, end - lineStart);
                                          formatted.push_back('\n');
                                          if (source[i] == '\r' && i + 1 < source.size() && source[i + 1] == '\n') ++i;
                                          lineStart = i + 1;
                                      }
                                  }
                                  if (lineStart < source.size()) {
                                      std::size_t end = source.size();
                                      while (end > lineStart && (source[end - 1] == ' ' || source[end - 1] == '\t')) --end;
                                      formatted.append(source, lineStart, end - lineStart);
                                      formatted.push_back('\n');
                                  }
                                  if (formatted.empty()) formatted = "\n";
                                  // Validate both streams with the compiler's own lexer before writing.
                                  // Parsing isn't required for formatting an in-progress source file.
                                  auto before = Lexer(source).tokenize(), after = Lexer(formatted).tokenize();
                                  if (before.size() != after.size())throw std::runtime_error("formatter changed token count; refusing to write");
                                  for (std::size_t i = 0; i < before.size(); ++i) {
                                      if (before[i].kind != after[i].kind || before[i].text != after[i].text)
                                          throw std::runtime_error("formatter changed lexical content; refusing to write");
                                  }
                                  return formatted;
                              }

                              static std::uint32_t archiveCRC32(const std::vector<std::uint8_t>& input) {
                                  std::uint32_t crc = 0xffffffffu;
                                  for (const auto byte : input) {
                                      crc ^= byte;
                                      for (int j = 0; j < 8; ++j) crc = (crc >> 1) ^ (0xedb88320u & (0u - (crc & 1u)));
                                  }
                                  return ~crc;
                              }
                              static std::vector<std::uint8_t> byteVector(const std::string& text) {
                                  return std::vector<std::uint8_t>(text.begin(), text.end());
                              }
                              static std::string jsonEscape(const std::string& input) {
                                  std::ostringstream out;
                                  for (unsigned char ch : input) {
                                      if (ch == '"')out << "\\\"";
                                      else if (ch == '\\')out << "\\\\";
                                      else if (ch == '\n')out << "\\n";
                                      else if (ch == '\r')out << "\\r";
                                      else if (ch == '\t')out << "\\t";
                                      else if (ch < 32) {
                                          const char* digits = "0123456789abcdef";
                                          out << "\\u00" << digits[ch >> 4] << digits[ch & 15];
                                      }
                                      else out << static_cast<char>(ch);
                                  }
                                  return out.str();
                              }
                              struct ArchiveFile { std::string name; std::vector<std::uint8_t> data; };
                              static std::vector<std::uint8_t> makeDeterministicZip(const std::vector<ArchiveFile>& files) {
                                  if (files.size() > 65535)throw std::runtime_error("E0593 ZIP supports at most 65535 entries");
                                  std::vector<std::uint8_t> out, central;
                                  const auto u16 = [](std::vector<std::uint8_t>& dst, std::uint16_t n) {dst.push_back(n & 255); dst.push_back((n >> 8) & 255); };
                                  const auto u32 = [](std::vector<std::uint8_t>& dst, std::uint32_t n) {for (int i = 0; i < 4; ++i)dst.push_back((n >> (8 * i)) & 255); };
                                  const auto length32 = [](std::size_t n)->std::uint32_t {
                                      if (n > 0xffffffffull)throw std::runtime_error("E0593 ZIP64 is not supported: file too large");
                                      return static_cast<std::uint32_t>(n);
                                      };
                                  std::set<std::string> names;
                                  for (const auto& file : files) {
                                      if (file.name.empty() || file.name.size() > 65535 || file.name.find("..") != std::string::npos)
                                          throw std::runtime_error("E0593 unsafe archive entry name");
                                      std::string canonical;
                                      for (unsigned char c : file.name) {
                                          if (!((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9') || c == '_' || c == '-' || c == '.' || c == '/'))
                                              throw std::runtime_error("E0593 archive entry names require portable ASCII path components");
                                          canonical += static_cast<char>(c >= 'a' && c <= 'z' ? c - ('a' - 'A') : c);
                                      }
                                      for (std::size_t start = 0; start <= canonical.size();) {
                                          const auto slash = canonical.find('/', start);
                                          const auto part = canonical.substr(start, slash == std::string::npos ? std::string::npos : slash - start);
                                          const auto base = part.substr(0, part.find('.'));
                                          if (part.empty() || part.back() == '.' || base == "CON" || base == "PRN" || base == "AUX" || base == "NUL" ||
                                              (base.size() == 4 && (base.starts_with("COM") || base.starts_with("LPT")) && base[3] >= '1' && base[3] <= '9'))
                                              throw std::runtime_error("E0593 unsafe or reserved archive path component");
                                          if (slash == std::string::npos) break;
                                          if (names.contains(canonical.substr(0, slash))) throw std::runtime_error("E0593 archive file/directory collision");
                                          start = slash + 1;
                                      }
                                      const auto descendant = names.lower_bound(canonical + '/');
                                      if ((descendant != names.end() && descendant->starts_with(canonical + '/')) || !names.insert(canonical).second)
                                          throw std::runtime_error("E0593 duplicate or colliding archive entry name");
                                      const auto pos = length32(out.size()), len = length32(file.data.size());
                                      const auto crc = archiveCRC32(file.data);
                                      // ZIP32 stored entries, fixed DOS date 1980-01-01, UTF-8 flag; reproducible.
                                      u32(out, 0x04034b50u); u16(out, 20); u16(out, 0x0800); u16(out, 0); u16(out, 0);
                                      u16(out, 0x0021); u32(out, crc); u32(out, len); u32(out, len);
                                      u16(out, static_cast<std::uint16_t>(file.name.size())); u16(out, 0);
                                      out.insert(out.end(), file.name.begin(), file.name.end());
                                      out.insert(out.end(), file.data.begin(), file.data.end());
                                      u32(central, 0x02014b50u); u16(central, 20); u16(central, 20); u16(central, 0x0800);
                                      u16(central, 0); u16(central, 0); u16(central, 0x0021); u32(central, crc);
                                      u32(central, len); u32(central, len); u16(central, static_cast<std::uint16_t>(file.name.size()));
                                      u16(central, 0); u16(central, 0); u16(central, 0); u16(central, 0); u32(central, 0); u32(central, pos);
                                      central.insert(central.end(), file.name.begin(), file.name.end());
                                  }
                                  const auto centralAt = length32(out.size()), centralSize = length32(central.size());
                                  out.insert(out.end(), central.begin(), central.end());
                                  u32(out, 0x06054b50u); u16(out, 0); u16(out, 0);
                                  u16(out, static_cast<std::uint16_t>(files.size())); u16(out, static_cast<std::uint16_t>(files.size()));
                                  u32(out, centralSize); u32(out, centralAt); u16(out, 0);
                                  return out;
                              }
                              static std::vector<std::uint8_t> buildDistribution(const std::string& source,
                                  const std::filesystem::path& sourcePath,
                                  const IRProgram& pcir,
                                  const std::string& entry,
                                  const PMIRProgram* pmir = nullptr,
                                  const MachineProgram* machine = nullptr) {
                                  PECOFFGenerator generator;
                                  auto executable = (pmir && machine) ? generator.emitExecutable(pcir, *pmir, *machine)
                                      : generator.emitExecutable(pcir, entry);
                                  auto object = (pmir && machine) ? generator.emitObject(pcir, *pmir, *machine)
                                      : generator.emitObject(pcir, entry);
                                  const auto original = sourcePath.filename().string();
                                  std::ostringstream manifest;
                                  manifest << "{\n  \"format\": \"paracine-development-bundle-v1\",\n"
                                      << "  \"compiler\": \"" << jsonEscape(kCompilerBuild) << "\",\n"
                                      << "  \"target\": \"windows-x86_64-pe32plus\",\n"
                                      << "  \"original_source\": \"" << jsonEscape(original) << "\",\n"
                                      << "  \"entry\": \"" << jsonEscape(entry.empty() ? "main" : entry) << "\",\n"
                                      << "  \"files\": [\"src/main.pcn\", \"bin/program.exe\", \"obj/program.obj\"]\n}\n";
                                  const std::string readme = "Paracine native Windows x64 development bundle\n"
                                      "This archive contains a Paracine source file and the emitted COFF/PE32+ binaries.\n"
                                      "This is a development-build artifact, not a certified Paracine 1.0 distribution.\n"
                                      "Run bin/program.exe on a compatible Windows x86-64 host after review.\n"
                                      "The file manifest.json describes the target and compiler edition.\n";
                                  return makeDeterministicZip({ { "manifest.json",byteVector(manifest.str()) },
                                       { "README.txt",byteVector(readme) },{ "src/main.pcn",byteVector(source) },
                                       { "obj/program.obj",std::move(object) },{ "bin/program.exe",std::move(executable) } });
                              }
                              static std::string formatPhaseTimings(const std::vector<std::pair<std::string, double>>& timings) {
                                  std::ostringstream out;
                                  out << "Paracine compiler phase profile (milliseconds, wall-clock)\n";
                                  double total = 0;
                                  for (const auto& item : timings) {
                                      out << "  " << std::left << std::setw(24) << item.first << " "
                                          << std::fixed << std::setprecision(3) << item.second << " ms\n"; total += item.second;
                                  }
                                  out << "  " << std::left << std::setw(24) << "TOTAL" << " " << std::fixed << std::setprecision(3) << total << " ms\n";
                                  return out.str();
                              }
                              static void initializeProject(const std::filesystem::path& root) {
                                  if (root.empty())throw std::runtime_error("init requires a directory path");
                                  std::error_code ec;
                                  if (std::filesystem::exists(root, ec)) {
                                      if (!std::filesystem::is_directory(root, ec) || !std::filesystem::is_empty(root, ec))
                                          throw std::runtime_error("init refuses to overwrite an existing nonempty path: " + root.string());
                                  }
                                  std::filesystem::create_directories(root / "src");
                                  writeTextFile(root / "src/main.pcn", "routine main() gives int\n    give 0\n");
                                  writeTextFile(root / "README.md", "# Paracine starter\n\n"
                                      "Build from this directory: `paracine build src/main.pcn -o main.exe`\n"
                                      "Run on Windows x86-64: `main.exe`\n"
                                      "The compiler is a development build; check supported features before deployment.\n");
                                  writeTextFile(root / ".gitignore", "*.exe\n*.obj\n*.pcir\n*.pmir\n*.asm\n*.zip\n");
                              }
                              static bool binaryAvailableOnPath(const std::string& binary) {
                                  std::string pathText;
#ifdef _WIN32
                                  // MSVC C4996: use the bounds-aware Windows CRT API rather than getenv.
                                  // _dupenv_s allocates a copy; std::free must release it on every path.
                                  char* raw = nullptr;
                                  std::size_t rawSize = 0;
                                  if (_dupenv_s(&raw, &rawSize, "PATH") != 0) {
                                      std::free(raw);
                                      return false;
                                  }
                                  std::unique_ptr<char, decltype(&std::free)> ownedPath(raw, &std::free);
                                  if (!ownedPath) return false;
                                  pathText.assign(ownedPath.get());
                                  constexpr char sep = ';';
                                  const std::string extension = ".exe";
#else
                                  const char* raw = std::getenv("PATH");
                                  if (!raw) return false;
                                  pathText.assign(raw);
                                  constexpr char sep = ':';
                                  const std::string extension = "";
#endif
                                  std::stringstream paths(pathText); std::string part;
                                  while (std::getline(paths, part, sep)) {
                                      auto path = std::filesystem::path(part) / binary;
                                      std::error_code ec;
                                      if (std::filesystem::is_regular_file(path, ec) || std::filesystem::is_regular_file(path.string() + extension, ec))return true;
                                  }
                                  return false;
                              }
                              static void printDoctor(std::ostream& out) {
                                  out << kCompilerBuild << "\nHost: ";
#if defined(_WIN32)
                                  out << "Windows";
#elif defined(__linux__)
                                  out << "Linux";
#else
                                  out << "other";
#endif
#if defined(_M_X64)||defined(__x86_64__)
                                  out << " x86-64\n";
#else
                                  out << " non-x86-64\n";
#endif
                                  out << "Compilation target: Windows x86-64 (COFF/PE32+)\n";
                                  for (const char* tool : { "cmake","clang++","g++","lld-link" })
                                      out << "External " << tool << ": " << (binaryAvailableOnPath(tool) ? "found" : "not found") << "\n";
                                  out << "Internal native linker: limited (external COFF linking uses lld-link adapter)\n"
                                      << "Language conformance: incomplete; this is NOT a 1.0 release.\n";
                              }

