                                              context.Rip = reinterpret_cast<DWORD64>(image.data()) + pc;
                                              context.Rsp = pc == 0 || pc == 63 ? rbp + 8 : pc == 1 || pc == 4 || pc == 62 ? rbp : rbp - frame;
                                              context.Rbp = pc == 0 || pc == 1 || pc == 63 ? savedRbp : rbp;
