                                      writeBinaryFile(file, PECOFFGenerator{}.emitExecutable(optimized.pcir, optimized.pmir, optimized.machine));
                                      if (runNativeExecutable(file) != 0) throw std::runtime_error("vectorized native execution mismatch");
                                      writeBinaryFile(file, PECOFFGenerator{}.emitExecutable(optimized.pcir, optimized.pmir, scalar));
                                      if (runNativeExecutable(file) != 0) throw std::runtime_error("scalar native execution mismatch");
                                      writeBinaryFile(file, PECOFFGenerator{}.emitExecutable(optimized.pcir, reversed, reversedMachine));
