                                              std::int64_t expected = 11;
                                              for (int i = 0; i < count; ++i) {
                                                  const int value = type == "long" ? (i % 2 ? 2 : -1) : (i % 2 ? i + 1 : -i - 1);
                                                  if (i) source += ", ";
                                                  source += type == "long" ? (i % 2 ? "positive" : "negative") : std::to_string(value);
                                                  expected += value;
                                              }
                                              source += "]\n    var sum: " + type + " = 11\n    for value in values\n        sum += value\n";
                                              source += "    if sum == " + std::to_string(expected) + "\n        give 0\n    give 1\n";
                                              CompilerOptions o3; o3.optimizationLevel = 3; o3.jobs = 1;
