                                      if (!hasDiagnostic(artifacts.analysis, "E0346 generic type argument exceeds identity size limit") || !artifacts.pcir.functions.empty())
                                          throw std::runtime_error("oversized generic identity did not produce a bounded diagnostic");
                                      const std::string source = "routine id<T>(value: T) gives T\n    give value\nroutine main() gives int\n    give id<int>(1)\n";
