                                          for (const auto& block : function.blocks) for (const auto& i : block.instructions) if (i.op == IROpcode::Mul) {
                                              if (block.id != function.blocks.front().id || !i.sourceSpan || i.sourceSpan->start.line != 5) throw std::runtime_error("invariant multiply or source location was not preserved in the preheader");
                                              hoisted = true;
                                          }
                                      if (!hoisted || !artifacts.analysis.succeeded() || PCIRInterpreter(artifacts.pcir).run("") != 42) throw std::runtime_error("loop invariant computation was not hoisted");
                                      const std::string mutableSource = "routine work(seed: int) gives int\n    var sum: int = 0\n    var state: int = seed\n    var index: int = 0\n    while index < 3\n        sum += state * state\n        state += 1\n        index += 1\n    give sum\nroutine main() gives int\n    if work(1) == 14\n        give 42\n    give 0\n";
                                      const auto mutableLoop = compileAll(mutableSource, options);
                                      if (!mutableLoop.analysis.succeeded() || PCIRInterpreter(mutableLoop.pcir).run("") != 42) throw std::runtime_error("loop-carried mutation was treated as invariant");
                                      const auto trap = compileAll("routine work(seed: int, count: int) gives int\n    var index: int = 0\n    while index < count\n        let invalid: int = seed / 0\n        index += 1\n    give 42\nroutine main() gives int\n    give work(1, 0)\n", options);
                                      bool divisionInLoop = false;
                                      for (const auto& function : trap.pcir.functions) if (function.name == "work")
                                          for (const auto& block : function.blocks) for (const auto& i : block.instructions) if (i.op == IROpcode::Div && block.id != function.blocks.front().id) divisionInLoop = true;
                                      if (!divisionInLoop || !trap.analysis.succeeded() || PCIRInterpreter(trap.pcir).run("") != 42) throw std::runtime_error("zero-trip loop speculated a division trap");
#if defined(_WIN32)
                                      const auto file = std::filesystem::temp_directory_path() / ("paracine-global-loop-" + std::to_string(std::chrono::steady_clock::now().time_since_epoch().count()) + ".exe");
                                      struct Cleanup { std::filesystem::path path; ~Cleanup() { std::error_code ec; std::filesystem::remove(path, ec); } } cleanup{ file };
                                      for (const auto* program : { &artifacts, &mutableLoop, &trap }) {
                                          writeBinaryFile(file, PECOFFGenerator{}.emitExecutable(program->pcir, program->pmir, program->machine));
                                          if (runNativeExecutable(file) != 42) throw std::runtime_error("global loop optimization differs from native execution");
                                      }
#endif
