                                  test("optimizer: module inlining growth budget", [&] {
                                      std::string expression = "x";
                                      for (int i = 0; i < 5; ++i) expression = "(" + expression + " * 3 + 1)";
                                      std::string src = "routine leaf(x: int) gives int\n    give " + expression +
                                          "\nroutine work(x: int) gives int\n    var sum: int = 0\n";
                                      for (int i = 0; i < 120; ++i) src += "    sum += leaf(x)\n";
                                      src += "    give sum\nroutine main() gives int\n    if work(1) == 43680\n        give 0\n    give 1\n";
                                      auto count = [](const IRProgram& p) {
                                          std::size_t n = 0;
                                          for (const auto& f : p.functions) for (const auto& b : f.blocks) n += b.instructions.size() + b.phiNodes.size();
                                          return n;
                                      };
                                      auto calls = [](const IRProgram& p) {
                                          std::size_t n = 0;
                                          for (const auto& f : p.functions) if (f.name == "work") for (const auto& b : f.blocks)
                                              for (const auto& i : b.instructions) if (i.op == IROpcode::Call && i.callee == "leaf") ++n;
                                          return n;
                                      };
                                      CompilerOptions o0; o0.optimizationLevel = 0;
                                      CompilerOptions o3; o3.optimizationLevel = 3; o3.jobs = 1;
                                      const auto baseline = compileAll(src, o0);
                                      const auto optimized = compileAll(src, o3);
                                      o3.jobs = 4;
                                      const auto parallel = compileAll(src, o3);
                                      if (!baseline.analysis.succeeded() || !optimized.analysis.succeeded() || !parallel.analysis.succeeded() ||
                                          count(optimized.pcir) > 3 * count(baseline.pcir) || calls(optimized.pcir) == 0 || calls(optimized.pcir) >= 120 ||
                                          irToString(optimized.pcir) != irToString(parallel.pcir) ||
                                          PCIRInterpreter(baseline.pcir).run("") != 0 || PCIRInterpreter(optimized.pcir).run("") != 0)
                                          throw std::runtime_error("inlining budget or program behavior incorrect");
#if defined(_WIN32)
                                      const auto file = std::filesystem::temp_directory_path() /
                                          ("paracine-inline-budget-" + std::to_string(std::uint64_t(std::chrono::steady_clock::now().time_since_epoch().count())) + ".exe");
                                      struct CleanupInlineBudget { std::filesystem::path path; ~CleanupInlineBudget() { std::error_code ec; std::filesystem::remove(path, ec); } } cleanup{ file };
                                      writeBinaryFile(file, PECOFFGenerator{}.emitExecutable(optimized.pcir, optimized.pmir, optimized.machine));
                                      if (runNativeExecutable(file) != 0) throw std::runtime_error("budgeted inlining native result differs");
#elif defined(__linux__) && defined(__x86_64__)
                                      if (executeEmittedMachineTextIsolated(optimized.machine) != 0) throw std::runtime_error("budgeted inlining native result differs");
#endif
                                  });
                                  struct ModuleFixture {
                                      std::filesystem::path root = std::filesystem::temp_directory_path() / ("paracine-modules-" + std::to_string(std::chrono::steady_clock::now().time_since_epoch().count()));
                                      std::set<std::filesystem::path> files, directories;
                                      ModuleFixture() { if (!std::filesystem::create_directory(root)) throw std::runtime_error("cannot create module fixture"); }
                                      void write(const std::filesystem::path& relative, const std::string& source) {
                                          const auto target = root / relative;
                                          for (auto parent = target.parent_path(); parent != root; parent = parent.parent_path()) directories.insert(parent);
                                          std::filesystem::create_directories(target.parent_path()); files.insert(target); writeTextFile(target, source);
                                      }
                                      CompilationArtifacts compile(const std::string& source, int level = 0, bool machine = false) {
                                          write("main.pcn", source); CompilerOptions options; options.optimizationLevel = level;
                                          return compileAll(source, options, machine, nullptr, root / "main.pcn");
                                      }
                                      bool rejects(const std::string& source, const std::string& code) {
                                          try { (void)compile(source); } catch (const std::runtime_error& error) { return std::string(error.what()).find(code) != std::string::npos; }
                                          return false;
                                      }
                                      ~ModuleFixture() {
                                          std::error_code ec;
                                          for (auto entry = std::filesystem::recursive_directory_iterator(root, ec); !ec && entry != std::filesystem::recursive_directory_iterator{}; entry.increment(ec)) {
                                              const auto path = entry->path();
                                              if (entry->is_directory(ec)) directories.insert(path);
                                              else files.insert(path);
                                          }
                                          if (ec) std::cerr << "module fixture cleanup discovery failed: " << ec.message() << "\n";
                                          for (const auto& file : files) std::filesystem::remove(file, ec);
                                          for (auto directory = directories.rbegin(); directory != directories.rend(); ++directory) std::filesystem::remove(*directory, ec);
                                          std::filesystem::remove(root, ec);
                                          if (ec) std::cerr << "module fixture cleanup failed: " << ec.message() << "\n";
                                      }
                                  };
