                                  test("optimizer: XOR register redefinitions preserve snapshots", [&] {
                                      CompilerOptions options; options.optimizationLevel = 0;
                                      const auto compiled = compileAll("routine f(x: int, key: int, replacement: int) gives int\n    give x\n"
                                          "routine main() gives int\n    give f(5, 3, 7)\n", options, false);
                                      if (!compiled.analysis.succeeded()) throw std::runtime_error("XOR register fixture failed semantic analysis");
                                      for (int which = 0; which < 3; ++which) {
                                          auto program = compiled.pcir;
                                          auto found = std::find_if(program.functions.begin(), program.functions.end(), [](const IRFunction& f) { return f.name == "f"; });
                                          if (found == program.functions.end() || found->blocks.size() != 1 || found->parameterVregs.size() != 3)
                                              throw std::runtime_error("unexpected XOR register fixture shape");
                                          auto& fn = *found;
                                          const auto left = fn.parameterVregs[0], right = fn.parameterVregs[1], replacement = fn.parameterVregs[2];
                                          const auto intermediate = static_cast<VReg>(++fn.totalVregs), result = static_cast<VReg>(++fn.totalVregs);
                                          IRInstruction first; first.op = IROpcode::BitXor; first.dest = intermediate; first.valueType = makeIRIntType(); first.args = { left, right };
                                          IRInstruction overwrite; overwrite.op = IROpcode::Copy; overwrite.dest = which == 0 ? left : which == 1 ? right : intermediate; overwrite.valueType = makeIRIntType(); overwrite.args = { replacement };
                                          IRInstruction second; second.op = IROpcode::BitXor; second.dest = result; second.valueType = makeIRIntType(); second.args = { intermediate, right };
                                          IRInstruction ret; ret.op = IROpcode::Return; ret.valueType = makeIRIntType(); ret.args = { result };
                                          fn.blocks[0].instructions = { first, overwrite, second, ret };
                                          if (!PCIRVerifier{}.verify(program).empty()) throw std::runtime_error("invalid XOR register fixture");
                                          const auto expected = which == 0 ? 5 : which == 1 ? 1 : 4;
                                          if (PCIRInterpreter(program).run("") != expected) throw std::runtime_error("incorrect XOR fixture result");
                                          PCIROptimizer(2, 1).optimize(program);
                                          if (!PCIRVerifier{}.verify(program).empty() || PCIRInterpreter(program).run("") != expected)
                                              throw std::runtime_error("XOR cancellation used a stale register version");
                                      }
                                  });
