                                          "routine commuted(x: int) gives int\n    if x == 0\n        give 0\n    give 2 * x\n"
                                          "routine wide(x: int) gives int\n    if x == 0\n        give 0\n    give x * 4294967296\n"
                                          "routine highbit(x: int) gives int\n    if x == 0\n        give 0\n    give x * (-9223372036854775807 - 1)\n"
                                          "routine nonpower(x: int) gives int\n    give x * 7\n"
                                          "routine negative(x: int) gives int\n    give x * -8\n"
                                          "routine main() gives int\n"
                                          "    if scale(-7) != -7168\n        give 1\n"
                                          "    if commuted(-9) != -18\n        give 2\n"
                                          "    if wide(4294967296) != 0\n        give 3\n"
                                          "    if nonpower(6) != 42\n        give 4\n"
                                          "    if negative(6) != -48\n        give 5\n"
                                          "    if highbit(-1) != (-9223372036854775807 - 1)\n        give 6\n"
                                          "    if highbit(2) != 0\n        give 7\n"
                                          "    give 42\n";
